/// Runs one request.
pub fn transition(s: &Snapshot, req: &Request) -> Result<Reply, Error> {
    let user = req.user;
    match &req.op {
        Op::Messages { room, from, to, dir, limit, filter } => {
            api_message::get_message_events_route(s, user, *room, *from, *to, *dir, *limit, filter)
        }
        Op::Context { room, event, limit, filter } => {
            api_context::get_context_route(s, user, *room, *event, *limit, filter)
        }
        Op::Relations { room, event, rel_type, event_type, from, to, limit, recurse, dir } => {
            api_relations::paginate_relations_with_filter(
                s, user, *room, *event, *event_type, *rel_type, *from, *to, *limit, *recurse, *dir,
            )
        }
        Op::Threads { room, from, limit, participated } => {
            api_threads::get_threads_route(s, user, *room, *from, *limit, *participated)
        }
        Op::State { room } => api_state::get_state_events_route(s, user, *room),
        Op::StateEvent { room, kind, state_key } => {
            api_state::get_state_events_for_key_route(s, user, *room, *kind, *state_key)
        }
        Op::Members { room, at, membership, not_membership } => {
            api_members::get_member_events_route(s, user, *room, *at, *membership, *not_membership)
        }
        Op::JoinedMembers { room } => api_members::joined_members_route(s, user, *room),
        Op::InitialSync { room, limit } => api_room::room_initial_sync_route(s, user, *room, *limit),
        Op::RoomEvent { room, event } => api_room::get_room_event_route(s, user, *room, *event),
        Op::ServerCanSee { origin, room, event } => {
            Ok(Reply::CanSee(svc_accessor::server_can_see_event(s, *origin, *room, *event)))
        }
    }
}

/// `room_initial_sync_route`: a user who left sees the room as of their
/// departure.
pub fn room_initial_sync_route(s: &Snapshot, user: u64, room: u64, limit: Option<u64>) -> Result<Reply, Error> {
    match svc_cache::user_membership(s, user, room) {
        Some(Membership::Ban) => return Err(Error::Forbidden),
        _ => {}
    }
    if !svc_accessor::user_can_see_state_events(s, user, room) {
        return Err(Error::Forbidden);
    }
    let current_shortstatehash = match svc_timeline::get_room_shortstatehash(s, room) {
        Ok(h) => h,
        Err(e) => return Err(e),
    };
    let member = match svc_accessor::state_get(s, current_shortstatehash, Kind::Member, user) {
        Ok(p) => Some(p),
        Err(Error::NotFound) => None,
        Err(e) => return Err(e),
    };
    let membership = match member {
        None => None,
        Some(p) => match s.pdus[p].membership {
            MemberField::Is(m) => Some(m),
            MemberField::Absent => return Err(Error::Parse),
        },
    };
    let departed = match membership {
        Some(Membership::Leave) => true,
        Some(Membership::Ban) => true,
        _ => false,
    };
    let (timeline_end, shortstatehash) = match member {
        Some(p) => {
            if departed {
                match departure_snapshot(s, room, &s.pdus[p], current_shortstatehash) {
                    Ok(x) => x,
                    Err(e) => return Err(e),
                }
            } else {
                (s.current_count, current_shortstatehash)
            }
        }
        None => (s.current_count, current_shortstatehash),
    };
    let limit = match limit {
        Some(l) => {
            if l < LIMIT_MAX { l } else { LIMIT_MAX }
        }
        None => LIMIT_MAX,
    };
    let state = match svc_accessor::state_full_pdus_strict(s, shortstatehash) {
        Ok(v) => v,
        Err(e) => return Err(e),
    };
    let it = match svc_timeline::pdus_rev(s, room, timeline_end.saturating_add(1)) {
        Ok(v) => v,
        Err(e) => return Err(e),
    };
    let mut events: Vec<(i64, usize)> = Vec::new();
    let mut i = 0;
    while i < it.len() && (events.len() as u64) < limit {
        let p = it[i];
        if api_message::visibility_filter(s, p, user) {
            events.push((s.pdus[p].count, p));
        }
        i += 1;
    }
    let events = reversed(&events);
    let start = if events.len() == 0 { None } else { Some(events[0].0) };
    let end = match api_message::last_count(&events) {
        Some(c) => c,
        None => timeline_end,
    };
    let mut state_ids = Vec::new();
    let mut j = 0;
    while j < state.len() {
        state_ids.push(s.pdus[state[j]].event_id);
        j += 1;
    }
    Ok(Reply::InitialSync { membership, state: state_ids, chunk: api_message::event_ids(s, &events), start, end })
}

/// `get_room_event_route`: one event, if visible and not ignored. The
/// release build does not check that the event is in `room`.
pub fn get_room_event_route(s: &Snapshot, user: u64, room: u64, event_id: u64) -> Result<Reply, Error> {
    let event = svc_timeline::get_pdu(s, event_id);
    let visible = svc_accessor::user_can_see_event(s, user, room, event_id);
    let p = match event {
        Ok(p) => p,
        Err(_) => return Err(Error::NotFound),
    };
    if !visible {
        return Err(Error::NotFound);
    }
    if api_message::is_ignored_pdu(s, &s.pdus[p], user) {
        return Err(Error::SenderIgnored);
    }
    Ok(Reply::RoomEvent { event: s.pdus[p].event_id })
}

/// `get_threads_route`. The ignore-list view (MSC3856) changes how a root
/// is presented, not which roots are listed.
pub fn get_threads_route(s: &Snapshot, user: u64, room: u64, from: Token, limit: Option<u64>, participated: bool) -> Result<Reply, Error> {
    if !svc_timeline::exists(s, room) {
        return Err(Error::Forbidden);
    }
    if !svc_accessor::user_can_see_room(s, user, room) {
        return Err(Error::Forbidden);
    }
    let limit = match limit {
        Some(l) => {
            if l < 100 { l } else { 100 }
        }
        None => 10,
    };
    let from = match from {
        Token::Invalid => return Err(Error::Parse),
        Token::At(c) => c,
        Token::Absent => COUNT_MAX,
    };
    let all = match svc_threads::threads_until(s, user, room, from, participated) {
        Ok(v) => v,
        Err(e) => return Err(e),
    };
    let mut threads: Vec<(i64, usize)> = Vec::new();
    let mut i = 0;
    while i < all.len() && (threads.len() as u64) < limit + 1 {
        let (count, p) = all[i];
        if svc_accessor::user_can_see_event(s, user, room, s.pdus[p].event_id) {
            threads.push((count, p));
        }
        i += 1;
    }
    let more = (threads.len() as u64) > limit;
    let threads = truncate(&threads, limit);
    let next_batch = if more { api_message::last_count(&threads) } else { None };
    Ok(Reply::Threads { chunk: api_message::event_ids(s, &threads), next_batch })
}

