/// GET `/_matrix/client/v3/rooms/{roomId}/initialSync`
pub(crate) async fn room_initial_sync_route(
	State(services): State<crate::State>,
	body: Ruma<Request>,
) -> Result<Response> {
	let room_id = &body.room_id;
	let sender_user = body.sender_user();

	// `user_membership` uses `Ban` when a once-joined user's left row was forgotten.
	let cached_membership = services
		.state_cache
		.user_membership(sender_user, room_id)
		.await;

	matches!(cached_membership.as_ref(), Some(MembershipState::Ban))
		.is_false()
		.ok_or_else(|| err!(Request(Forbidden("No room preview available."))))?;

	services
		.state_accessor
		.user_can_see_state_events(sender_user, room_id)
		.await
		.ok_or_else(|| err!(Request(Forbidden("No room preview available."))))?;

	let current_shortstatehash = services
		.state
		.get_room_shortstatehash(room_id)
		.await?;

	let member = services
		.state_accessor
		.state_get(current_shortstatehash, &RoomMember, sender_user.as_str())
		.await
		.optional()?;

	let membership = member
		.as_ref()
		.map(Event::get_content)
		.transpose()?
		.map(|content: RoomMemberEventContent| content.membership);

	let next_batch = services.globals.current_count();
	let departure = membership
		.as_ref()
		.filter(|membership| matches!(membership, MembershipState::Leave | MembershipState::Ban))
		.zip(member.as_ref())
		.map(|(membership, pdu)| {
			departure_snapshot(
				&services,
				room_id,
				pdu,
				membership.to_owned(),
				current_shortstatehash,
			)
			.left_future()
		});

	let current_snapshot = ok((PduCount::Normal(next_batch), current_shortstatehash, membership));
	let (timeline_end, shortstatehash, membership) = departure
		.unwrap_or_else(|| current_snapshot.right_future())
		.await?;

	let visibility = services.directory.visibility(room_id).map(Ok);
	let limit = body.limit.unwrap_or(LIMIT_MAX).min(LIMIT_MAX);
	let state = services
		.state_accessor
		.state_full_pdus_strict(shortstatehash)
		.map_ok(Event::into_format)
		.try_collect::<Vec<_>>();

	let events = services
		.timeline
		.pdus_rev(Some(sender_user), room_id, Some(timeline_end.saturating_add(1)))
		.wide_and_then(|item| visibility_filter(&services, item, sender_user).map(Ok))
		.ready_try_filter_map(Ok)
		.try_take(limit)
		.try_collect()
		.map_ok(|mut vec: Vec<_>| {
			vec.reverse();
			vec
		});

	let account_data = services
		.account_data
		.changes_since_fallible(
			Some(room_id),
			sender_user,
			0,
			Some(timeline_end.into_normal().into_unsigned()),
		)
		.ready_try_filter_map(|e| Ok(extract_variant!(e, AnyRawAccountDataEvent::Room)))
		.try_collect::<Vec<_>>();

	let (visibility, state, events, account_data) = try_join4(visibility, state, events, account_data)
			.boxed() // erase the state stream's higher-ranked event lifetime
			.await?;

	Ok(Response {
		room_id: room_id.to_owned(),
		membership,
		visibility: visibility.into(),
		account_data: Some(account_data),
		state: state.into(),
		messages: PaginationChunk {
			start: events
				.first()
				.map(at!(0))
				.as_ref()
				.map(ToString::to_string),

			end: events
				.last()
				.map(at!(0))
				.as_ref()
				.map_or_else(|| timeline_end.to_string(), ToString::to_string),

			chunk: events
				.into_iter()
				.map(at!(1))
				.map(Event::into_format)
				.collect(),
		}
		.into(),
	})
}

pub(crate) async fn get_room_event_route(
	State(services): State<crate::State>,
	body: Ruma<get_room_event::v3::Request>,
) -> Result<get_room_event::v3::Response> {
	let sender_user = body.sender_user();
	let event_id = &body.event_id;
	let room_id = &body.room_id;

	let event = services
		.timeline
		.get_pdu(event_id)
		.map_err(|_| err!(Request(NotFound("Event {} not found.", event_id))));

	let retained_event = body
		.include_unredacted_content
		.then_async(async || {
			let is_admin = services.admin.user_is_admin(sender_user);

			let can_redact = services
				.config
				.allow_room_admins_to_request_unredacted_events
				.then_async(|| {
					services
						.state_accessor
						.get_power_levels(room_id)
						.map_ok_or(false, |power_levels| {
							power_levels.for_user(sender_user) >= power_levels.redact
						})
				})
				.unwrap_or(false);

			pin_mut!(is_admin, can_redact);

			if is_admin.or(can_redact).await {
				services
					.retention
					.get_original_pdu(event_id)
					.await
					.map_err(|_| err!(Request(NotFound("Event {} not found.", event_id))))
			} else {
				Err!(Request(Forbidden("You are not allowed to see the original event")))
			}
		});

	let visible = services
		.state_accessor
		.user_can_see_event(sender_user, room_id, event_id);

	let (mut event, retained_event, visible): (Result<Pdu>, Option<Result<Pdu>>, _) =
		join3(event, retained_event, visible).await;

	if event.as_ref().is_err_or(Event::is_redacted)
		&& let Some(retained_event) = retained_event
	{
		event = retained_event;
	}

	let mut event = event?;

	if !visible {
		return Err!(Request(NotFound("Event not found.")));
	}

	if is_ignored_pdu(&services, &event, body.sender_user()).await {
		return Err!(HttpJson(NOT_FOUND, {
			"errcode": "M_SENDER_IGNORED",
			"error": "You have ignored the user that sent this event",
			"sender": event.sender().as_str(),
		}));
	}

	debug_assert!(
		event.event_id() == event_id && event.room_id() == room_id,
		"Fetched PDU must match requested"
	);

	event.add_age().ok();

	let encrypted = services
		.state_accessor
		.is_encrypted_room(room_id)
		.await;

	annotate_membership(&services, &mut event, sender_user, encrypted).await;

	let event = services
		.pdu_metadata
		.bundle_aggregations(sender_user, event)
		.await;

	Ok(get_room_event::v3::Response { event: event.into_format() })
}

pub(crate) async fn get_threads_route(
	State(services): State<crate::State>,
	ref body: Ruma<get_threads::v1::Request>,
) -> Result<get_threads::v1::Response> {
	let sender_user = body.sender_user();
	let room_id = &body.room_id;

	if !services.metadata.exists(room_id).await {
		return Err!(Request(Forbidden("Room does not exist to this server")));
	}

	if !services
		.state_accessor
		.user_can_see_room(sender_user, room_id)
		.await
	{
		return Err!(Request(Forbidden("You don't have permission to view this room.")));
	}

	// Use limit or else 10, with maximum 100
	let limit = body
		.limit
		.map(usize::try_from)
		.flat_ok()
		.unwrap_or(10)
		.min(100);

	let from: PduCount = body
		.from
		.as_deref()
		.map(str::parse)
		.transpose()?
		.unwrap_or_else(PduCount::max);

	// MSC3856: the requester's ignore list adjusts the served threads.
	let ignored: BTreeSet<OwnedUserId> = services
		.account_data
		.get_global(sender_user, GlobalAccountDataEventType::IgnoredUserList)
		.await
		.map(|event: IgnoredUserListEvent| event.content.ignored_users.into_keys().collect())
		.unwrap_or_default();

	// One extra row probes whether the list continues past this page.
	let mut threads: Vec<(PduCount, PduEvent)> = services
		.threads
		.threads_until(sender_user, room_id, from, &body.include)
		.try_filter_map(async |(count, pdu)| {
			Ok(services
				.state_accessor
				.user_can_see_event(sender_user, room_id, &pdu.event_id)
				.await
				.then_some((count, pdu)))
		})
		.and_then(async |(count, pdu)| {
			let view = match ignored.is_empty() {
				| true => IgnoredThreadView::Unchanged,
				| false =>
					services
						.pdu_metadata
						.ignored_thread_view(sender_user, &ignored, &pdu)
						.await,
			};

			Ok((count, pdu, view))
		})
		.take(limit.saturating_add(1))
		.wide_and_then(async |(count, pdu, view)| {
			let pdu = services
				.pdu_metadata
				.bundle_aggregations(sender_user, pdu)
				.await;

			Ok((count, apply_ignored_view(pdu, view)))
		})
		.try_collect()
		.await?;

	let more = threads.len() > limit;

	threads.truncate(limit);

	Ok(get_threads::v1::Response {
		next_batch: threads
			.last()
			.filter(|_| more)
			.map(at!(0))
			.as_ref()
			.map(ToString::to_string),

		chunk: threads
			.into_iter()
			.map(at!(1))
			.map(Event::into_format)
			.collect(),
	})
}

